    "title": "継続的な負荷検証を目指して",
    "abstract": "サービスを継続的に運用するにあたり、定期的な負荷検証はとても大事です。例えばあるリリースで、あるエンドポイントにN+1クエリが含まれてしまった場合、たった数行のコードがサービスダウンを起こしてしまうこともあります。\r\nしかし、継続開発されているサービスは常に新しいコードが生まれ、その新しいコードに対してのシナリオを開発し続けることは容易なことではありません。\r\n上記の課題に対して、AIを用いて課題解決を行い、継続的に負荷検証をできる状態にした事例を共有します。",
