    "title": "セキュリティ対策、何から始める？ — CloudNative環境の脅威モデリングとリスク評価実践入門",
    "abstract": "CloudNative の普及により、Kubernetes をはじめとするコンテナ基盤を本番環境で運用するチームが増えてきました。しかしその一方で、従来の境界防御を前提としたセキュリティ設計はこうした環境ではうまく機能しません。\r\nワークロードは動的に生成・破棄され、内部通信も信頼できず、どこから守るべきかを判断できない状態に陥りがちです。その結果、対策は増えていくのに設計だけが複雑化していきます。\r\n本セッションでは、SaaS アーキテクチャを例に Kubernetes 環境の脅威モデリングを段階的に実践します。STRIDE フレームワークによる脅威の洗い出し、リスクアセスメントによる対策の優先順位決定、そしてその結果を具体的な設計にどう落とし込むかまでの一連のプロセスを紹介します。\r\n",
    "speakers": [
      {
        "id": 2213,
        "name": "Subaru Nakamura",
        "nameKanji": "中村　昴",
        "userId": 1176
      }
    ],
