    "videoPlatform": null,
    "videoId": "https://d3pun3ptcv21q4.cloudfront.net/mediapackage/cnk/talks/3049/271/playlist.m3u8",
    "title": "インフラエンジニアのナレッジ価値を最大化する最適解。AI活用のためのグローバルクラウドネイティブ基盤",
    "abstract": "社内のナレッジマネジメントシステムをクラウドネイティブなコンテナ基盤へ移行した実践事例を公開！\n共有の心理的障壁を下げるリアクション機能や検索性を高めるタグ付け機能、生成AI連携による自動要約機能など、現場が「使いたくなる」工夫を紹介します。\nインフラ組織の生産性を変える攻めのシステム刷新の全貌と、グローバルでノウハウを共有できる機能などさらなる発展を見据えた構想を開発の裏側と共にお届けします。",
