    "title": "DX時代の開発プロセスに組み込む脆弱性診断  ― AIで実装するシフトレフト",
    "abstract": "DXの加速により、開発スピードとセキュリティ強化の両立がこれまで以上に求められています。しかし、従来の開発終盤でまとめて実施する診断では、手戻りやリリース遅延が発生しがちです。本セッションでは、AIを活用した脆弱性診断の自動化・仕組み化により、専門知識に依存せず開発プロセスへセキュリティを組み込む方法を解説。DXを推進しながら、開発基盤に自然に組み込めるシフトレフトの具体像を、デモを交えてご紹介します。",
