    "videoId": "https://d3pun3ptcv21q4.cloudfront.net/mediapackage/cnk/talks/3053/296/playlist.m3u8",
    "title": "境界を溶かすエンジニアリング ― サイロを超える技術と文化のデザイン",
    "abstract": "生成AIは驚異的な速度でコードを書きます。しかし同時に、驚異的な速度で車輪を再発明してもいます。重複したロジック、冗長なインフラ、散在するナレッジ ― 生産性が上がるほど、組織のどこかに静かに積み上がるものがあります。それを技術的負債にするか、共創の起点にするかは仕組みと文化の問題です。世界中の企業のInnerSource導入から見えてきた、AI時代に「増やさない力」を育てるためのヒントをお伝えします。",
    "speakers": [
      {
        "id": 2297,
        "name": "Yuki Hattori",
        "nameKanji": "服部 佑樹",
        "userId": 1536
      }
    ],
