    "title": "Platform Engineering for Agents",
    "abstract": "AI エージェントにも従来のアプリと同様、堅牢なセキュリティや可観測性が不可欠です。本セッションでは、Platform Engineering を Agentic Application 向けに適用していく方法を解説します。AI ゲートウェイ、MCP の統合や様々なコントロールプレーンを IDP に組み込み、ガバナンスと開発速度を両立しつつ本番運用に乗せるためのアーキテクチャ設計を考えていきます。",
