    "videoId": "https://d3pun3ptcv21q4.cloudfront.net/mediapackage/cnk/talks/3065/300/playlist.m3u8",
    "title": "SREの仕事は「壊さないこと」ではなくなった  〜自律化していくシステムに、責任と判断を与えるという価値〜 ",
    "abstract": "自律化が進む現代でSREとして現場に向き合う中で、私はSREの価値は「壊れないシステムを作ること」だけでは不十分になりつつあると感じるようになりました。\r\n\r\nでは、いまSREの価値はどこにあるのでしょうか。\r\n\r\n本セッションでは、CloudNativeを「変化と劣化を前提とした設計思想」と捉え直し、SREがどの立場で関わり、どこまで責任を引き受けるべきかを考えます。\r\n\r\nAIによってシステムの自律化が進む時代に、人が引き受けるべき「責任」と「判断」とは何か。\r\n\r\n実体験をもとに、AI時代におけるSREの価値を考えます。",
    "speakers": [
      {
        "id": 2296,
        "name": "Naoki Shimada",
        "nameKanji": "島田 直樹",
        "userId": 1250
      }
    ],
